/**
 * `<map-geometry>` — a semantic container for a feature's shape markup
 * (`<map-point>`/`<map-linestring>`/`<map-polygon>`/`<map-multi*>`/
 * `<map-geometrycollection>`). Ported from MapML.js `src/map-geometry.js`; the
 * actual parsing happens in `mapml/features/parseGeometry.js`.
 */
export class HTMLGeometryElement extends HTMLElement {
  static get observedAttributes() {
    return ['cs'];
  }
  get cs() {
    return this.getAttribute('cs');
  }
  set cs(val) {
    if (['tcrs', 'tilematrix', 'pcrs', 'gcrs', 'map', 'tile'].includes(val)) {
      this.setAttribute('cs', val);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    switch (name) {
      case 'cs': {
        if (oldValue !== newValue) {
          // handle side effects
        }
        break;
      }
    }
  }
  constructor() {
    super();
  }
  connectedCallback() {}
  disconnectedCallback() {}
}
