/**
 * Shared helpers for building the per-`<map-layer>` / per-`<map-extent>`
 * layer-control fieldsets. Extracted so both elements build the same markup
 * without depending on the control itself.
 */

let controlIdCounter = 0;

// Monotonic id source used for the `id`/`aria-labelledby` pairs on the
// layer-name span and opacity summary. Replaces MapML.js's Leaflet `stamp()`.
export function nextControlId() {
  return ++controlIdCounter;
}

const SVGNS = 'http://www.w3.org/2000/svg';

// The "settings" (three vertical dots) icon, path data verbatim from MapML.js's
// createLayerControlForLayer.js.
export function settingsControlSvg() {
  const svg = document.createElementNS(SVGNS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('height', '22');
  svg.setAttribute('width', '22');
  svg.setAttribute('fill', 'currentColor');
  const path1 = document.createElementNS(SVGNS, 'path');
  path1.setAttribute('d', 'M0 0h24v24H0z');
  path1.setAttribute('fill', 'none');
  const path2 = document.createElementNS(SVGNS, 'path');
  path2.setAttribute(
    'd',
    'M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z'
  );
  svg.append(path1, path2);
  return svg;
}
