/**
 * `FeatureInteraction` — hover tooltip + click popup for `<map-feature>`s.
 *
 * MapML.js implements feature interactivity on focusable SVG `<g>`/`<path>`
 * DOM produced by its Leaflet `featureRenderer` (see `map-feature._setUpEvents`
 * / `MapLayer._attachSkipButtons`). OpenLayers draws features to a canvas, so
 * there is no per-feature DOM to focus or listen on. This map-level handler is
 * the re-architected analog: it hit-tests features under the pointer and
 *   - shows a hover tooltip carrying the feature caption
 *     (`<map-featurecaption>` or `locale.dfFeatureCaption`), and
 *   - on click, re-dispatches a cancelable `click` event on the owning
 *     `<map-feature>` element (preserving the `addEventListener('click')`
 *     contract) and, if the feature has `<map-properties>`, toggles a popup
 *     rendering that content plus a "zoom to here" link.
 *
 * Both tooltip and popup are `ol/Overlay`s mounted in the map's overlay
 * container. Keyboard/focus navigation of features (the popup skip-buttons and
 * feature index) belongs with the deferred a11y focus-proxy overlay slice.
 */
import Overlay from 'ol/Overlay.js';

export class FeatureInteraction {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    // The <map-feature> whose popup is currently open, or null.
    this._openFeatureEl = null;

    this._tooltipEl = document.createElement('div');
    this._tooltipEl.className = 'mapml-feature-tooltip';
    this._tooltipEl.hidden = true;
    this._tooltip = new Overlay({
      element: this._tooltipEl,
      offset: [14, 0],
      positioning: 'center-left',
      stopEvent: false
    });

    this._popupEl = document.createElement('div');
    this._popupEl.className = 'mapml-popup';
    this._popupEl.hidden = true;
    this._popup = new Overlay({
      element: this._popupEl,
      offset: [0, -12],
      positioning: 'bottom-center',
      autoPan: true,
      stopEvent: true
    });

    this._map.addOverlay(this._tooltip);
    this._map.addOverlay(this._popup);

    this._onPointerMove = this._onPointerMove.bind(this);
    this._onSingleClick = this._onSingleClick.bind(this);
    this._onPopupKeyDown = this._onPopupKeyDown.bind(this);
    this._popupEl.addEventListener('keydown', this._onPopupKeyDown);
    this._map.on('pointermove', this._onPointerMove);
    this._map.on('singleclick', this._onSingleClick);
  }

  destroy() {
    this._map.un('pointermove', this._onPointerMove);
    this._map.un('singleclick', this._onSingleClick);
    this._map.removeOverlay(this._tooltip);
    this._map.removeOverlay(this._popup);
    this._openFeatureEl = null;
  }

  // The first hit-tested feature that belongs to a <map-feature>, or null.
  _featureAtPixel(pixel) {
    return this._map.forEachFeatureAtPixel(
      pixel,
      (feature) => (feature._featureEl ? feature : null),
      { hitTolerance: 4 }
    );
  }

  _featureCaption(featureEl) {
    const caption = featureEl.querySelector('map-featurecaption');
    return caption
      ? caption.textContent
      : this._viewer.locale.dfFeatureCaption;
  }

  _onPointerMove(e) {
    if (e.dragging) return;
    const feature = this._featureAtPixel(e.pixel);
    const target = this._map.getTargetElement();
    if (feature) {
      if (target) target.style.cursor = 'pointer';
      this._tooltipEl.textContent = this._featureCaption(feature._featureEl);
      this._tooltipEl.hidden = false;
      this._tooltip.setPosition(e.coordinate);
    } else {
      if (target) target.style.cursor = '';
      this._tooltipEl.hidden = true;
      this._tooltip.setPosition(undefined);
    }
  }

  _onSingleClick(e) {
    const feature = this._featureAtPixel(e.pixel);
    if (!feature) {
      // Clicking the map background closes any open popup (Leaflet's
      // closePopupOnClick default).
      this.closePopup();
      return;
    }
    const featureEl = feature._featureEl;
    // Preserve the element-level API: a cancelable `click` on the
    // <map-feature>. User handlers may preventDefault() to suppress the popup.
    const clickEv = new PointerEvent('click', { cancelable: true });
    clickEv.originalEvent = e.originalEvent;
    featureEl.dispatchEvent(clickEv);
    if (clickEv.defaultPrevented) return;
    if (!featureEl.querySelector('map-properties')) return;
    if (this._openFeatureEl === featureEl) {
      this.closePopup();
    } else {
      this.openPopup(featureEl, e.coordinate);
    }
  }

  isPopupOpenFor(featureEl) {
    return this._openFeatureEl === featureEl;
  }

  // Escape from an open popup closes it and returns focus to the source
  // feature (matches MapML.js, where the tooltip reappears on the feature).
  _onPopupKeyDown(e) {
    if (e.key !== 'Escape') return;
    e.preventDefault();
    e.stopPropagation();
    const featureEl = this._openFeatureEl;
    this.closePopup();
    if (!featureEl) return;
    if (!this._viewer._featureIndex?.focusFeature(featureEl)) {
      this._viewer.focus();
    }
  }

  // The view-projection centre of a feature's geometry (PCRS == view CRS).
  _featureCoordinate(featureEl) {
    const geometry = featureEl._olFeature?.getGeometry();
    if (!geometry) return null;
    const [minX, minY, maxX, maxY] = geometry.getExtent();
    return [(minX + maxX) / 2, (minY + maxY) / 2];
  }

  openPopup(featureEl, coordinate) {
    const properties = featureEl.querySelector('map-properties');
    if (!properties) return;
    const coord = coordinate ?? this._featureCoordinate(featureEl);
    if (!coord) return;

    const locale = this._viewer.locale;
    this._popupEl.replaceChildren();
    this._popupEl.setAttribute('role', 'dialog');

    const closeButton = document.createElement('button');
    closeButton.type = 'button';
    closeButton.className = 'mapml-popup-close-button';
    closeButton.setAttribute('aria-label', 'Close popup');
    closeButton.innerHTML = "<span aria-hidden='true'>&#215;</span>";
    closeButton.addEventListener('click', () => this.closePopup());

    const content = document.createElement('div');
    content.className = 'mapml-popup-content';
    content.setAttribute('tabindex', '-1');
    content.setAttribute('role', 'document');
    content.insertAdjacentHTML('afterbegin', properties.innerHTML);

    const zoomLink = document.createElement('a');
    zoomLink.href = '#';
    zoomLink.className = 'mapml-zoom-link';
    zoomLink.textContent = locale.popupZoom;
    zoomLink.addEventListener('click', (ev) => {
      ev.preventDefault();
      featureEl.zoomTo();
      this.closePopup();
    });

    this._popupEl.append(closeButton, content, zoomLink);
    this._popupEl.append(this._buildSkipButtons(featureEl, locale));
    this._popupEl.hidden = false;
    this._popup.setPosition(coord);
    this._openFeatureEl = featureEl;
    this._viewer.dispatchEvent(new CustomEvent('mapml:contentpopupopen'));
    content.focus();
  }

  // The keyboard skip-button nav bar appended to every feature popup. Ported
  // from MapML.js `MapLayer._attachSkipButtons`: focus-map | prev | count |
  // next | focus-controls. Feature-to-feature navigation and the map/control
  // focus jumps are delegated to the map-level `FeatureIndex`.
  _buildSkipButtons(featureEl, locale) {
    const index = this._viewer._featureIndex;
    const nav = document.createElement('nav');
    nav.className = 'mapml-focus-buttons';

    const button = (glyph, title, onClick) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-popup-button';
      btn.title = title;
      btn.innerHTML = `<span aria-hidden='true'>${glyph}</span>`;
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        onClick();
      });
      return btn;
    };

    // Inline/static feature popups represent a single feature: "1/1". The
    // counter only paginates for query-result popups (which set a total feature
    // count); those land in Phase 7. Mirrors MapML.js `_attachSkipButtons`
    // (`totalFeatures = this._totalFeatureCount ? this._totalFeatureCount : 1`).
    const count = document.createElement('p');
    count.className = 'mapml-feature-count';
    count.textContent = '1/1';

    nav.append(
      button('|&#10094;', locale.kbdFocusMap, () => index?.focusMap()),
      button('&#10094;', locale.kbdPrevFeature, () =>
        index?.previousFeature(featureEl)
      ),
      count,
      button('&#10095;', locale.kbdNextFeature, () =>
        index?.nextFeature(featureEl)
      ),
      button('&#10095;|', locale.kbdFocusControls, () =>
        index?.focusControls()
      )
    );

    const divider = document.createElement('hr');
    divider.className = 'mapml-popup-divider';
    const wrapper = document.createDocumentFragment();
    wrapper.append(divider, nav);
    return wrapper;
  }

  closePopup() {
    if (!this._openFeatureEl) return;
    this._popupEl.hidden = true;
    this._popup.setPosition(undefined);
    this._openFeatureEl = null;
    this._viewer.dispatchEvent(new CustomEvent('mapml:contentpopupclose'));
  }
}
