/**
 * `FeatureIndexOverlay` — the feature-index accessibility overlay: a centred
 * reticle box plus an `aria-live` `<output>` that lists the features whose
 * bounding box overlaps the reticle, numbered `1`..`7` with `8`/`9` paging.
 *
 * Faithful port of MapML.js's `src/mapml/layers/FeatureIndexOverlay.js` (a
 * Leaflet `Layer`), re-architected for OpenLayers following MapML-MapLibre's
 * adaptation:
 *   - The in-viewport feature set + per-feature activation come from the
 *     viewer's {@link FeatureIndex} handler (`getInboundEntries()` /
 *     `onEntriesChanged()`) instead of Leaflet's `map.featureIndex`.
 *   - Reticle bounds and the overlap test run in the view projection (PCRS)
 *     directly against each feature's extent — OL feature geometries are
 *     already in view-projection coords — rather than going via GCRS.
 *   - List rows are built with DOM nodes + `textContent` so author captions
 *     can't inject markup.
 *
 * Behaviour parity: keys `1`–`7` activate the matching feature (popup if it
 * has `<map-properties>`, else focus); key `9` pages forward ("More results"),
 * key `8` back ("Previous results"); "No features found" when nothing overlaps;
 * the `<output>` is visually hidden until {@link enable}d so sighted users see
 * only the reticle, which itself hides behind an open feature popup.
 */
import { boundingExtent, intersects } from 'ol/extent.js';

/** Square reticle outline, mirrors MapML.js's FeatureIndexOverlay SVG. */
const RETICLE_SVG =
  '<svg xmlns="http://www.w3.org/2000/svg" xml:space="preserve" viewBox="0 0 100 100">' +
  '<path fill="none" stroke="#000" stroke-linecap="round" stroke-linejoin="round" ' +
  'stroke-width="3" d="M0 0h100v100H0z" color="#000" overflow="visible"/></svg>';

/** Reticle box width as a fraction of the map container (CSS `width: 16%`). */
const RETICLE_FRACTION = 0.16;

/** Features shown per page before paging kicks in. */
const PAGE_SIZE = 7;

// Resolve the tri-state user/UA feature-index preference from M.options.
// `undefined` == no preference (the button toggles freely); `'on'`/`'off'`
// force the overlay state and disable the button. The mapml-extension injects
// the legacy boolean `true`, which migrates to `'on'`. A default/absent value
// (`false`/`undefined`) means "not forced" so the control still works.
export function featureIndexPreference() {
  const opt = window.M?.options?.featureIndexOverlayOption;
  if (opt === true || opt === 'on') return 'on';
  if (opt === 'off') return 'off';
  return undefined;
}

export class FeatureIndexOverlay {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    this._host = viewer._featureIndex;
    this._locale = viewer.locale;

    this._pages = [];
    this._pageIndex = 0;
    this._active = false;
    this._popupOpen = false;
    this._unsubscribeHost = null;

    const container = this._map.getViewport();

    this._box = document.createElement('div');
    this._box.className = 'mapml-feature-index-box';
    this._box.innerHTML = RETICLE_SVG;
    this._box.setAttribute('hidden', '');
    container.appendChild(this._box);

    this._output = document.createElement('output');
    this._output.className = 'mapml-feature-index mapml-screen-reader-output';
    this._output.setAttribute('role', 'status');
    this._output.setAttribute('aria-live', 'polite');
    this._output.setAttribute('aria-atomic', 'true');
    container.appendChild(this._output);

    this._body = document.createElement('span');
    this._body.className = 'mapml-feature-index-content';
    this._output.appendChild(this._body);

    this._checkOverlap = this._checkOverlap.bind(this);
    this._onKeyDown = this._onKeyDown.bind(this);
    this._onPopupOpen = this._onPopupOpen.bind(this);
    this._onPopupClose = this._onPopupClose.bind(this);
  }

  // Show the reticle + results overlay and start tracking the map. Rebuilds
  // the results now and whenever the host's inbound set changes.
  enable() {
    if (this._active) return;
    this._active = true;
    this._output.classList.remove('mapml-screen-reader-output');
    this._unsubscribeHost = this._host.onEntriesChanged(this._checkOverlap);
    const container = this._map.getViewport();
    container.addEventListener('keydown', this._onKeyDown);
    this._viewer.addEventListener('mapml:contentpopupopen', this._onPopupOpen);
    this._viewer.addEventListener(
      'mapml:contentpopupclose',
      this._onPopupClose
    );
    this._syncBoxVisibility();
    this._checkOverlap();
  }

  // Hide the overlay and stop tracking the map.
  disable() {
    if (!this._active) return;
    this._active = false;
    this._popupOpen = false;
    this._output.classList.add('mapml-screen-reader-output');
    this._unsubscribeHost?.();
    this._unsubscribeHost = null;
    const container = this._map.getViewport();
    container.removeEventListener('keydown', this._onKeyDown);
    this._viewer.removeEventListener(
      'mapml:contentpopupopen',
      this._onPopupOpen
    );
    this._viewer.removeEventListener(
      'mapml:contentpopupclose',
      this._onPopupClose
    );
    this._syncBoxVisibility();
  }

  get active() {
    return this._active;
  }

  destroy() {
    this.disable();
    this._box.remove();
    this._output.remove();
  }

  _onPopupOpen() {
    this._popupOpen = true;
    this._syncBoxVisibility();
  }

  _onPopupClose() {
    this._popupOpen = false;
    this._syncBoxVisibility();
  }

  // Reticle box is visible only while active with no popup open over it.
  _syncBoxVisibility() {
    if (this._active && !this._popupOpen) this._box.removeAttribute('hidden');
    else this._box.setAttribute('hidden', '');
  }

  // Reticle bounds in view-projection coords: take the container-centre pixel,
  // expand by half the reticle box on each axis, and unproject the corners.
  // Ports MapML.js's `_calculateReticleBounds` (which does this in PCRS).
  // Returns null before the map's first render, when the size is unknown or
  // getCoordinateFromPixel can't resolve a frame state yet.
  _calculateReticleBounds() {
    const size = this._map.getSize();
    if (!size || !(size[0] > 0) || !(size[1] > 0)) return null;
    const cx = size[0] / 2;
    const cy = size[1] / 2;
    let reticlePx = this._box.getBoundingClientRect().width;
    if (!(reticlePx > 0)) reticlePx = size[0] * RETICLE_FRACTION;
    const half = reticlePx / 2;
    const a = this._map.getCoordinateFromPixel([cx - half, cy + half]);
    const b = this._map.getCoordinateFromPixel([cx + half, cy - half]);
    if (!a || !b) return null;
    return boundingExtent([a, b]);
  }

  // Rebuild the results list from the host's in-viewport features, keeping
  // only those whose extent overlaps the reticle. Ports `_checkOverlap`.
  _checkOverlap() {
    const reticle = this._calculateReticleBounds();
    // Map not rendered yet; recompute once entries change / the map moves.
    if (!reticle) return;
    const entries = this._host.getInboundEntries();

    this._body.replaceChildren();
    this._pageIndex = 0;
    this._pages = [];

    let index = 1;
    for (const entry of entries) {
      if (!intersects(reticle, entry.extent)) continue;

      if (index <= PAGE_SIZE) {
        this._body.appendChild(this._updateOutput(entry.label, index, index));
      }
      if ((index - 1) % PAGE_SIZE === 0) {
        this._pages.push([]);
      }
      this._pages[Math.floor((index - 1) / PAGE_SIZE)].push({
        label: entry.label,
        index,
        activate: entry.activate
      });
      // As soon as a second page starts, surface the "More results" (9) row.
      if (this._pages[1] && this._pages[1].length === 1) {
        this._body.appendChild(
          this._updateOutput(this._locale.fIndexMoreResults, 0, 9)
        );
      }
      index += 1;
    }

    this._addToggleKeys();

    if (index === 1) {
      const noFeatures = document.createElement('span');
      noFeatures.textContent = this._locale.fIndexNoFeatures;
      this._body.appendChild(noFeatures);
    }
  }

  // Build one row: <span data-index><kbd>key</kbd> label<span>, </span></span>.
  // The trailing ", " is a screen-reader auditory pause (hidden via CSS).
  // Uses textContent so captions can't inject markup. Ports `_updateOutput`.
  _updateOutput(label, index, key) {
    const span = document.createElement('span');
    span.setAttribute('data-index', String(index));
    const kbd = document.createElement('kbd');
    kbd.textContent = String(key);
    span.appendChild(kbd);
    span.appendChild(document.createTextNode(' ' + label));
    const pause = document.createElement('span');
    pause.textContent = ', ';
    span.appendChild(pause);
    return span;
  }

  // Append the paging toggle rows ("Previous results"/"More results") to each
  // page's model so `_newContent` can render them with keys 8/9. Ports
  // `_addToggleKeys`.
  _addToggleKeys() {
    const pages = this._pages;
    for (let i = 0; i < pages.length; i++) {
      if (pages[i].length === 0) return;
      if (pages[i - 1]) {
        pages[i].push({ label: this._locale.fIndexPreviousResults, index: 0 });
      }
      if (pages[i + 1] && pages[i + 1].length > 0) {
        pages[i].push({ label: this._locale.fIndexMoreResults, index: 0 });
      }
    }
  }

  // Render the page `direction` steps away from the one currently shown.
  // Ports `_newContent`.
  _newContent(direction) {
    const first = this._body.firstElementChild;
    if (!first) return;
    const currentIndex = Number(first.getAttribute('data-index'));
    const targetPage =
      this._pages[Math.floor((currentIndex - 1) / PAGE_SIZE) + direction];
    if (!targetPage || targetPage.length === 0) return;

    this._body.replaceChildren();
    this._pageIndex += direction;
    for (let i = 0; i < targetPage.length; i++) {
      const feature = targetPage[i];
      let key = i + 1;
      if (feature.label === this._locale.fIndexMoreResults) key = 9;
      if (feature.label === this._locale.fIndexPreviousResults) key = 8;
      this._body.appendChild(this._updateOutput(feature.label, feature.index, key));
    }
  }

  // Number-key handler: `1`–`7` activate the matching feature on the current
  // page; `8`/`9` page backwards/forwards. Ports `_onKeyDown`.
  _onKeyDown(e) {
    if (e.key >= '1' && e.key <= '7') {
      const page = this._pages[this._pageIndex];
      if (!page) return;
      const feature = page[Number(e.key) - 1];
      if (feature && feature.activate) feature.activate();
    } else if (e.key === '8') {
      this._newContent(-1);
    } else if (e.key === '9') {
      this._newContent(1);
    }
  }
}
