/*
 * Proj.CRS adapter — a thin replacement for proj4leaflet's `Proj.CRS` +
 * Leaflet's `CRS` base, backing all projection math with native `proj4`.
 *
 * MapML.js builds its `M[projection]` objects with proj4leaflet, which is
 * itself a Leaflet-flavoured wrapper over proj4. In the OpenLayers port the
 * real forward/inverse projection is delegated to `proj4` directly (OL also
 * consumes proj4 defs natively), so we only re-implement the small, fixed
 * method surface that the rest of the ported MapML.js code actually calls:
 * `project`, `unproject`, `scale`, `zoom`, `latLngToPoint`, `pointToLatLng`,
 * `getProjectedBounds`, `transformation`, `distance`/`R`. The numeric CRS
 * tables (origin/bounds/resolutions/crs.*) live verbatim in GlobalM.js.
 */

import proj4 from 'proj4';
import { Point } from '../../geometry/Point.js';
import { Bounds } from '../../geometry/Bounds.js';
import { Transformation } from '../../geometry/Transformation.js';
import { LatLng } from '../LatLng.js';
import { Earth } from '../Earth.js';

const Proj = {};

Proj.CRS = class {
  constructor(code, def, options) {
    options = options || {};

    // Register the projection with proj4 (native). `def` is the proj4/WKT
    // string; when omitted the code must already be known to proj4
    // (e.g. the built-in EPSG:3857 / EPSG:4326).
    if (def) {
      proj4.defs(code, def);
    }
    this._proj = proj4(code);
    this.code = code;
    this.options = options;

    // Same origin-based affine Leaflet/proj4leaflet build.
    this.transformation = options.origin
      ? new Transformation(1, -options.origin[0], -1, options.origin[1])
      : new Transformation(1, 0, -1, 0);

    if (options.resolutions) {
      this._scales = [];
      for (let i = options.resolutions.length - 1; i >= 0; i--) {
        if (options.resolutions[i]) {
          this._scales[i] = 1 / options.resolutions[i];
        }
      }
    }

    this.infinite = !options.bounds;

    // CRS.Earth mixins used by callers that measure ground distance.
    this.distance = Earth.distance;
    this.R = Earth.R;
  }

  // @method project(latlng: LatLng): Point
  project(latlng) {
    const point = this._proj.forward([latlng.lng, latlng.lat]);
    return new Point(point[0], point[1]);
  }

  // @method unproject(point: Point): LatLng
  // 0-over-NaN fallback matches proj4leaflet's handling of out-of-bounds points.
  unproject(point) {
    const p = this._proj.inverse([point.x, point.y]);
    return new LatLng(p[1] || 0, p[0] || 0);
  }

  // @method scale(zoom: Number): Number
  scale(zoom) {
    const iZoom = Math.floor(zoom);
    if (zoom === iZoom) {
      return this._scales[zoom];
    }
    // Non-integer zoom, interpolate
    const baseScale = this._scales[iZoom];
    const nextScale = this._scales[iZoom + 1];
    return baseScale + (nextScale - baseScale) * (zoom - iZoom);
  }

  // @method zoom(scale: Number): Number
  zoom(scale) {
    const downScale = this._closestElement(this._scales, scale);
    const downZoom = this._scales.indexOf(downScale);
    if (scale === downScale) {
      return downZoom;
    }
    if (downScale === undefined) {
      return -Infinity;
    }
    const nextScale = this._scales[downZoom + 1];
    if (nextScale === undefined) {
      return Infinity;
    }
    return (scale - downScale) / (nextScale - downScale) + downZoom;
  }

  // @method latLngToPoint(latlng: LatLng, zoom: Number): Point
  latLngToPoint(latlng, zoom) {
    return this.transformation._transform(
      this.project(latlng),
      this.scale(zoom)
    );
  }

  // @method pointToLatLng(point: Point, zoom: Number): LatLng
  pointToLatLng(point, zoom) {
    return this.unproject(
      this.transformation.untransform(point, this.scale(zoom))
    );
  }

  // @method getProjectedBounds(zoom: Number): Bounds
  getProjectedBounds(zoom) {
    if (this.infinite) {
      return null;
    }
    const b = this.options.bounds,
      s = this.scale(zoom),
      min = this.transformation.transform(b.min, s),
      max = this.transformation.transform(b.max, s);
    return new Bounds(min, max);
  }

  _closestElement(array, element) {
    let low;
    for (let i = array.length; i--;) {
      if (array[i] <= element && (low === undefined || low < array[i])) {
        low = array[i];
      }
    }
    return low;
  }
};

export default Proj;
