/**
 * `<map-layer>` — a named, toggleable layer. Named `HTMLLayerElement` to match
 * MapML.js, where a `<map-layer>` *is* a Leaflet `LayerGroup`; here it owns an
 * `ol/layer/Group` added to the map. Child `<map-extent>` groups and tile
 * layers are pushed into it in DOM order (index === render z-order).
 *
 * `checked` drives group visibility; `opacity` drives group opacity. The layer
 * control markup/events are built by `getLayerControlHTML()` (ported from
 * MapML.js's createLayerControlForLayer.js).
 */
/* global M */
import LayerGroup from 'ol/layer/Group.js';
import { createLayerControlForLayer } from './mapml/elementSupport/layers/createLayerControlForLayer.js';
import { MapFeatureLayer } from './mapml/layers/MapFeatureLayer.js';
import { Util } from './mapml/utils/Util.js';
import { toBounds as bounds } from './mapml/geometry/Bounds.js';

export class HTMLLayerElement extends HTMLElement {
  static get observedAttributes() {
    return ['label', 'checked', 'hidden', 'opacity'];
  }

  constructor() {
    super();
    this._settingsExpanded = false;
    // Dedup key for the "no projection assigned" warning (see getProjection).
    this.loggedMessages = new Set();
  }

  get label() {
    return this.getAttribute('label') || '';
  }

  // The layer's extent envelope (pcrs/gcrs/tcrs/tilematrix corners + zoom),
  // ported from MapML.js layer.js. Bounds are (re)derived on every read.
  get extent() {
    this._calculateBounds();
    return this.bounds
      ? Object.assign(
          Util._convertAndFormatPCRS(
            this.bounds,
            window.M[this.getProjection()],
            this.getProjection()
          ),
          { zoom: this.zoomBounds }
        )
      : null;
  }

  get checked() {
    return this.hasAttribute('checked');
  }
  set checked(value) {
    if (value) {
      this.setAttribute('checked', '');
    } else {
      this.removeAttribute('checked');
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) {
      return;
    }
    if (name === 'checked') {
      this._layerGroup?.setVisible(this.checked);
    } else if (name === 'opacity' && newValue !== null) {
      this._layerGroup?.setOpacity(Number(newValue));
    }
  }

  // Reflect opacity to the group (called by the layer-control opacity slider).
  setOpacity(value) {
    this.setAttribute('opacity', String(value));
    this._layerGroup?.setOpacity(Number(value));
  }

  async connectedCallback() {
    this._viewer = this.closest('mapml-viewer');
    if (!this._viewer) {
      return;
    }
    await this._viewer.whenReady();
    if (!this.isConnected) {
      return;
    }
    this.getLayerGroup();
    this._notifyLayersChanged();
  }

  disconnectedCallback() {
    if (this._layerGroup && this._viewer?.map) {
      this._viewer.map.removeLayer(this._layerGroup);
    }
    this._layerGroup = null;
    this._notifyLayersChanged();
  }

  _notifyLayersChanged() {
    this._viewer?.dispatchEvent(new CustomEvent('mapml:layerschanged'));
  }

  // Lazily create the group (and attach it to the map) so descendants can
  // obtain it regardless of custom-element upgrade order.
  getLayerGroup() {
    if (this._layerGroup) {
      return this._layerGroup;
    }
    this._viewer = this._viewer || this.closest('mapml-viewer');
    this._layerGroup = new LayerGroup({ layers: [], visible: this.checked });
    this._viewer.map.addLayer(this._layerGroup);
    return this._layerGroup;
  }

  // Lazily create the layer's static-feature vector layer (the `_mapmlvectors`
  // member, MapML.js MapLayer). One per <map-layer>; child <map-feature>
  // elements add their ol/Feature to it. Added to the layer's ol/Group so it
  // inherits visibility/opacity and z-order.
  _getFeatureLayer() {
    if (this._mapmlvectors) {
      return this._mapmlvectors;
    }
    this._mapmlvectors = new MapFeatureLayer({
      projection: this.getProjection(),
      mapEl: this._viewer
    });
    this.getLayerGroup().getLayers().push(this._mapmlvectors);
    return this._mapmlvectors;
  }

  // Build the per-layer fieldset for the layer control. Delegates to the
  // ported createLayerControlForLayer.js builder (kept standalone to diff 1:1
  // against MapML.js).
  getLayerControlHTML(locale) {
    return createLayerControlForLayer(this, locale);
  }

  // Derive this.bounds (PCRS) + this.zoomBounds from the layer's own
  // <map-meta name="extent"|"zoom"> unioned with the bounds/zoom of every child
  // <map-extent> and the layer's static-feature vector layer (_mapmlvectors).
  // Ported from MapML.js MapLayer.js `_calculateBounds`; the inline-tile
  // (<map-tile>) branch lands when that element is ported. Falls back to the
  // whole projection extent + zoom range for a layer with no bounds source.
  _calculateBounds() {
    delete this.bounds;
    delete this.zoomBounds;
    const projection = this.getProjection();
    let bnds = this.querySelector(':scope > map-meta[name=extent][content]')
      ? Util.getBoundsFromMeta(this)
      : undefined;
    let zoomBounds = this.querySelector(':scope > map-meta[name=zoom][content]')
      ? Util.getZoomBoundsFromMeta(this)
      : undefined;
    const mapExtents = this.querySelectorAll(':scope > map-extent');
    let zoomMax, zoomMin, minNativeZoom, maxNativeZoom;
    if (zoomBounds) {
      zoomMax = zoomBounds.maxZoom;
      zoomMin = zoomBounds.minZoom;
      maxNativeZoom = zoomBounds.maxNativeZoom
        ? zoomBounds.maxNativeZoom
        : -Infinity;
      minNativeZoom = zoomBounds.minNativeZoom
        ? zoomBounds.minNativeZoom
        : Infinity;
    }
    for (let i = 0; i < mapExtents.length; i++) {
      mapExtents[i]._calculateBounds();
      let mapExtentLayer = mapExtents[i]._extentGroup;
      if (mapExtentLayer?.bounds) {
        if (!bnds) {
          bnds = bounds(mapExtentLayer.bounds.min, mapExtentLayer.bounds.max);
        } else {
          bnds.extend(mapExtentLayer.bounds);
        }
        if (mapExtentLayer.zoomBounds) {
          if (!zoomBounds) {
            zoomBounds = mapExtentLayer.zoomBounds;
          } else {
            // Extend layer zoombounds
            zoomMax = Math.max(zoomMax, mapExtentLayer.zoomBounds.maxZoom);
            zoomMin = Math.min(zoomMin, mapExtentLayer.zoomBounds.minZoom);
            maxNativeZoom = Math.max(
              maxNativeZoom,
              mapExtentLayer.zoomBounds.maxNativeZoom
            );
            minNativeZoom = Math.min(
              minNativeZoom,
              mapExtentLayer.zoomBounds.minNativeZoom
            );
            zoomBounds.minZoom = zoomMin;
            zoomBounds.maxZoom = zoomMax;
            zoomBounds.minNativeZoom = minNativeZoom;
            zoomBounds.maxNativeZoom = maxNativeZoom;
          }
        }
      }
    }
    // _mapmlvectors: union the static-feature vector layer's bounds/zoom.
    const featureLayers = this._layerGroup
      ? this._layerGroup
          .getLayers()
          .getArray()
          .filter((l) => l instanceof MapFeatureLayer)
      : [];
    for (const layer of featureLayers) {
      if (layer.layerBounds) {
        if (!bnds) {
          bnds = bounds(layer.layerBounds.min, layer.layerBounds.max);
        } else {
          bnds.extend(layer.layerBounds);
        }
      }
      if (layer.zoomBounds) {
        if (!zoomBounds) {
          zoomBounds = layer.zoomBounds;
          zoomMax = zoomBounds.maxZoom;
          zoomMin = zoomBounds.minZoom;
          maxNativeZoom = zoomBounds.maxNativeZoom ?? -Infinity;
          minNativeZoom = zoomBounds.minNativeZoom ?? Infinity;
        } else {
          zoomMax = Math.max(zoomMax, layer.zoomBounds.maxZoom);
          zoomMin = Math.min(zoomMin, layer.zoomBounds.minZoom);
          maxNativeZoom = Math.max(maxNativeZoom, layer.zoomBounds.maxNativeZoom);
          minNativeZoom = Math.min(minNativeZoom, layer.zoomBounds.minNativeZoom);
          zoomBounds.minZoom = zoomMin;
          zoomBounds.maxZoom = zoomMax;
          zoomBounds.minNativeZoom = minNativeZoom;
          zoomBounds.maxNativeZoom = maxNativeZoom;
        }
      }
    }
    if (bnds) {
      this.bounds = bnds;
    } else {
      let projectionBounds = M[projection].options.bounds;
      this.bounds = bounds(projectionBounds.min, projectionBounds.max);
    }
    // we could get here and zoomBounds might still not be defined (empty layer)
    if (!zoomBounds) zoomBounds = {};
    if (!zoomBounds.minZoom) {
      zoomBounds.minZoom = 0;
    }
    if (!zoomBounds.maxZoom) {
      zoomBounds.maxZoom = M[projection].options.resolutions.length - 1;
    }
    if (zoomBounds.minNativeZoom === Infinity) {
      zoomBounds.minNativeZoom = zoomBounds.minZoom;
    }
    if (zoomBounds.maxNativeZoom === -Infinity) {
      zoomBounds.maxNativeZoom = zoomBounds.maxZoom;
    }
    this.zoomBounds = zoomBounds;
  }

  // Resolve the layer's projection: its own <map-meta name="projection">, else a
  // unanimous <map-extent units>, else the parent viewer's projection (warning
  // once when nothing declares one). Ported from MapML.js layer.js; the src /
  // shadowRoot (remote-layer) branch lands with <map-layer src>.
  getProjection() {
    let mapml = this;
    let projection = this.parentElement.projection;
    if (mapml.querySelector('map-meta[name=projection][content]')) {
      projection =
        Util._metaContentToObject(
          mapml
            .querySelector('map-meta[name=projection]')
            .getAttribute('content')
        ).content || projection;
    } else if (mapml.querySelector('map-extent[units]')) {
      const getProjectionFrom = (extents) => {
        let extentProj = extents[0].attributes.units.value;
        let isMatch = true;
        for (let i = 0; i < extents.length; i++) {
          if (extentProj !== extents[i].attributes.units.value) {
            isMatch = false;
          }
        }
        return isMatch ? extentProj : null;
      };
      projection =
        getProjectionFrom(
          Array.from(mapml.querySelectorAll('map-extent[units]'))
        ) || projection;
    } else {
      const message = `A projection was not assigned to the '${mapml.label}' Layer. \nPlease specify a projection for that layer using a map-meta element. \nSee more here - https://maps4html.org/web-map-doc/docs/elements/meta/`;
      if (!this.loggedMessages.has(message)) {
        console.log(message);
        this.loggedMessages.add(message);
      }
    }
    return projection;
  }
}
